    <script>
        // Sticky header on scroll
        const header = document.getElementById('header');
        window.addEventListener('scroll', () => {
            header.classList.toggle('scrolled', window.scrollY > 60);
        }, { passive: true });

        // Burger menu toggle
        const burger = document.getElementById('burger');
        const navLinks = document.getElementById('navLinks');
        burger.addEventListener('click', () => {
            const open = navLinks.classList.toggle('open');
            burger.classList.toggle('active', open);
            burger.setAttribute('aria-expanded', open);
        });
        document.querySelectorAll('.nav-links a').forEach(a => {
            a.addEventListener('click', () => {
                navLinks.classList.remove('open');
                burger.classList.remove('active');
                burger.setAttribute('aria-expanded', 'false');
            });
        });

        // Smooth scroll for anchor links
        document.querySelectorAll('a[href^="#"]').forEach(a => {
            a.addEventListener('click', function(e) {
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    e.preventDefault();
                    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            });
        });

        // Fade-in on scroll via IntersectionObserver
        const fadeObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                    fadeObserver.unobserve(entry.target);
                }
            });
        }, { threshold: 0.12 });

        document.querySelectorAll('.fade-in').forEach(el => fadeObserver.observe(el));

        // Contact form — AJAX submit
        document.querySelector('.contact-form').addEventListener('submit', function (e) {
            e.preventDefault();
            const form = this;
            const notice = document.getElementById('form-notice');
            const btn = form.querySelector('button[type="submit"]');

            notice.style.display = 'none';
            notice.className = 'form-notice';
            btn.disabled = true;
            btn.textContent = 'Отправка…';

            fetch('send.php', { method: 'POST', body: new FormData(form) })
                .then(r => r.json())
                .then(data => {
                    if (data.ok) {
                        notice.textContent = 'Заявка отправлена! Мы свяжемся с вами в ближайшее время.';
                        notice.classList.add('success');
                        form.reset();
                    } else {
                        notice.textContent = 'Ошибка отправки. Пожалуйста, попробуйте позже или позвоните нам.';
                        notice.classList.add('error');
                    }
                })
                .catch(() => {
                    notice.textContent = 'Ошибка отправки. Пожалуйста, попробуйте позже или позвоните нам.';
                    notice.classList.add('error');
                })
                .finally(() => {
                    notice.style.display = 'block';
                    notice.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    btn.disabled = false;
                    btn.textContent = 'Отправить заявку';
                });
        });
    </script>

